import json
from dataclasses import dataclass
from typing import List
import jsonschema
from mashumaro.jsonschema import build_json_schema


@dataclass
class SimpleChild:
    name: str


@dataclass  
class SimpleParent:
    id: str
    child: SimpleChild


def test_nested_validation():
    """Test nested dataclasses validation with all_refs=True"""
    print("=== Testing Nested Dataclasses Validation with all_refs=True ===")

    schema_with_refs = build_json_schema(SimpleParent, all_refs=True)
    schema_dict = json.loads(schema_with_refs.to_json())
    print("Generated schema with all_refs=True:")
    print(json.dumps(schema_dict, indent=2))

    # Sample data that should validate
    sample_data = {
        "id": "parent-1",
        "child": {
            "name": "child-1"
        }
    }

    print(f"\nSample data to validate: {sample_data}")

    try:
        jsonschema.validate(sample_data, schema_dict)
        print("✓ Validation succeeded")
        return False
    except Exception as e:
        print(f"✗ Validation failed: {e}")
        print(f"Error type: {type(e)}")
        return True


if __name__ == "__main__":
    validation_failed = test_nested_validation()
    if validation_failed:
        print("\n✗ Nested validation failed!")
    else:
        print("\n✓ Nested validation succeeded")

